<?php declare(strict_types=1);require __DIR__.'/../../includes/bootstrap.php';require_student();require_once __DIR__.'/../../includes/services.php';verify_csrf($_POST['csrf_token']??null);$uid=(int)current_user()['user_id'];if(empty($_FILES['csv'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK||$_FILES['csv']['size']>2097152){flash('import_error','Choose a CSV file up to 2 MB.');redirect('student/import.php');}$fh=fopen($_FILES['csv']['tmp_name'],'rb');$header=fgetcsv($fh);if(!$header){flash('import_error','CSV is empty.');redirect('student/import.php');}$map=[];foreach($header as$i=>$h)$map[strtolower(trim((string)$h))]=$i;foreach(['date','type','amount','description']as$required){if(!isset($map[$required])){flash('import_error','Missing column: '.$required);redirect('student/import.php');}}$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO import_batches(user_id,file_name,status,started_at) VALUES(?,? ,"processing",CURRENT_TIMESTAMP)')->execute([$uid,$_FILES['csv']['name']]);$bid=(int)$pdo->lastInsertId();$rowNo=1;$total=0;$ok=0;$bad=0;while(($row=fgetcsv($fh))!==false){$total++;$date=trim((string)($row[$map['date']]??''));$type=strtolower(trim((string)($row[$map['type']]??'')));$amount=(float)($row[$map['amount']]??0);$desc=trim((string)($row[$map['description']]??''));if(!valid_date($date)||!in_array($type,['income','expense'],true)||$amount<=0||$desc===''){$bad++;$rowNo++;continue;}$cat=null;if(isset($map['category'])){$cn=trim((string)($row[$map['category']]??''));if($cn!==''){$q=$pdo->prepare('SELECT category_id FROM categories WHERE name=? AND type=? AND is_active=1 AND (is_default=1 OR user_id=?) ORDER BY is_default DESC LIMIT 1');$q->execute([$cn,$type,$uid]);$cat=$q->fetchColumn();}}$ai=suggest_category($uid,$desc,$type);$cat=$cat?(int)$cat:($ai['category_id']??0);if(!$cat){$bad++;$rowNo++;continue;}$pdo->prepare('INSERT INTO transactions(user_id,category_id,import_batch_id,amount,type,description,ai_suggested_category_id,source,transaction_date) VALUES(?,?,?,?,?,?,?,"csv_import",?)')->execute([$uid,$cat,$bid,$amount,$type,$desc,$ai['category_id']??null,$date]);$tid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO import_rows(import_batch_id,row_number,raw_data,transaction_id,suggested_category_id,status) VALUES(?,?,?,?,?,"imported")')->execute([$bid,$rowNo,json_encode($row),$tid,$ai['category_id']??null]);$ok++;$rowNo++;}$pdo->prepare('UPDATE import_batches SET total_rows=?,imported_rows=?,failed_rows=?,status=?,completed_at=CURRENT_TIMESTAMP WHERE import_batch_id=?')->execute([$total,$ok,$bad,$bad?'completed_with_errors':'completed',$bid]);$pdo->commit();add_activity($uid,'create','import_batch',$bid,['imported'=>$ok,'failed'=>$bad]);flash('import_success',"Import complete: {$ok} imported, {$bad} skipped.");}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());flash('import_error','Import failed.');}fclose($fh);redirect('student/import.php');